	ID       string
	Data     []byte
	State    ItemState
	LeaseID  string
	ClaimAt  time.Time
	AckedAt  *time.Time
}

// Lease holds a worker's exclusive claim over a batch of items.
type Lease struct {
	ID        string
	Items     []*Item
	CreatedAt time.Time
	ExpiresAt time.Time
}

// Queue manages items with lease-based batch claiming.
type Queue struct {
	mu    sync.RWMutex
	items map[string]*Item
	// itemOrder tracks insertion order for FIFO claiming
	itemOrder []*Item
}

// New creates a new queue.
func New() *Queue {
	return &Queue{
		items:     make(map[string]*Item),
		itemOrder: make([]*Item, 0),
	}
}

// Add appends an item to the queue. Returns the item ID.
func (q *Queue) Add(data []byte) string {
	q.mu.Lock()
	defer q.mu.Unlock()

	id := uuid.New().String()
	item := &Item{
		ID:      id,
		Data:    data,
		State:   Pending,
		ClaimAt: time.Now(),
	}
	q.items[id] = item
	q.itemOrder = append(q.itemOrder, item)
	return id
}

// ClaimBatch claims up to 50 pending items under a new lease.
// Items are marked in-flight and the lease expiration is set to duration from now.
func (q *Queue) ClaimBatch(duration time.Duration) *Lease {
	q.mu.Lock()
	defer q.mu.Unlock()

	const batchSize = 50
	claimed := make([]*Item, 0, batchSize)

	for _, item := range q.itemOrder {
		if len(claimed) >= batchSize {
			break
		}
		if item.State == Pending {
			claimed = append(claimed, item)
		}
	}

	if len(claimed) == 0 {
		return nil
	}

	leaseID := uuid.New().String()
	now := time.Now()
	expiresAt := now.Add(duration)

	for _, item := range claimed {
		item.State = InFlight
		item.LeaseID = leaseID
	}

	return &Lease{
		ID:        leaseID,
		Items:     claimed,
		CreatedAt: now,
		ExpiresAt: expiresAt,
	}
}

// Ack marks items in a lease as acked. Items remain acked and won't be claimed again.
func (q *Queue) Ack(leaseID string, itemIDs []string) error {
	q.mu.Lock()
	defer q.mu.Unlock()

	now := time.Now()
	for _, id := range itemIDs {
		item, exists := q.items[id]
		if !exists {
			continue
		}
		if item.LeaseID == leaseID && item.State == InFlight {
			item.State = Acked
			ackedAt := now
			item.AckedAt = &ackedAt
		}
	}
	return nil
}

// ReleaseExpiredLeases marks in-flight items from expired leases back to pending.
// This allows other workers to claim them again.
func (q *Queue) ReleaseExpiredLeases(now time.Time) {
	q.mu.Lock()
	defer q.mu.Unlock()

	for _, item := range q.itemOrder {
		if item.State == InFlight {
			// Check if the item's lease has expired
			// We compare against item.ClaimAt + lease duration, but we need to track lease expiry separately
			// For now, we'll track via a separate lease map (see improved version below)
		}
	}
}

// Stats returns queue statistics.
func (q *Queue) Stats() map[string]int {
	q.mu.RLock()
	defer q.mu.RUnlock()

	stats := map[string]int{
		"total":     len(q.items),
		"pending":   0,
		"in_flight": 0,
		"acked":     0,
	}

	for _, item := range q.items {
		switch item.State {
		case Pending:
			stats["pending"]++
		case InFlight:
			stats["in_flight"]++
		case Acked:
			stats["acked"]++
		}
	}

	return stats
}

// Get retrieves an item by ID.
func (q *Queue) Get(itemID string) *Item {
	q.mu.RLock()
	defer q.mu.RUnlock()

	return q.items[itemID]
}

