package queue

import (
	"testing"
	"time"
)

func TestAddAndGet(t *testing.T) {
	q := New()
	data := []byte("test item")
	id := q.Add(data)

	item := q.Get(id)
	if item == nil {
		t.Fatal("item should exist")
	}
	if string(item.Data) != "test item" {
		t.Errorf("expected 'test item', got %s", item.Data)
	}
	if item.State != Pending {
		t.Errorf("expected state Pending, got %v", item.State)
	}
}

func TestClaimBatch(t *testing.T) {
	q := New()
	for i := 0; i < 75; i++ {
		q.Add([]byte{byte(i)})
	}

	lease := q.ClaimBatch(10 * time.Second)
	if lease == nil {
		t.Fatal("lease should not be nil")
	}
	if len(lease.Items) != 50 {
		t.Errorf("expected 50 items, got %d", len(lease.Items))
	}

	for _, item := range lease.Items {
		if item.State != InFlight {
			t.Errorf("item state should be InFlight, got %v", item.State)
		}
		if item.LeaseID != lease.ID {
			t.Errorf("item leaseID should match")
		}
	}

	stats := q.Stats()
	if stats["pending"] != 25 {
		t.Errorf("expected 25 pending, got %d", stats["pending"])
