import (
	"fmt"
	"log"
	"time"

	"queue/queue"
)

// Example worker that processes items from the queue.
// Demonstrates the claim-process-ack workflow.
func main() {
	q := queue.New()

	// Seed the queue with some items
	for i := 1; i <= 125; i++ {
		q.Add([]byte(fmt.Sprintf("task-%d", i)))
	}

	fmt.Printf("Initial stats: %v\n", q.Stats())

	// Worker 1: Claim and process a batch
	worker1Lease := q.ClaimBatch(30 * time.Second)
	if worker1Lease == nil {
		log.Fatal("failed to claim batch for worker 1")
	}
	fmt.Printf("Worker 1 claimed %d items (lease: %s)\n", len(worker1Lease.Items), worker1Lease.ID[:8])
	fmt.Printf("Stats after worker 1 claim: %v\n", q.Stats())

	// Simulate processing: worker 1 acks first 40 items
	itemsToAck := make([]string, 0)
	for i := 0; i < 40; i++ {
		itemsToAck = append(itemsToAck, worker1Lease.Items[i].ID)
	}
	q.Ack(worker1Lease.ID, itemsToAck)
	fmt.Printf("Worker 1 acked %d items\n", len(itemsToAck))
	fmt.Printf("Stats after worker 1 ack: %v\n", q.Stats())

	// Worker 2: Claim next batch
	worker2Lease := q.ClaimBatch(30 * time.Second)
	if worker2Lease == nil {
		log.Fatal("failed to claim batch for worker 2")
	}
	fmt.Printf("Worker 2 claimed %d items (lease: %s)\n", len(worker2Lease.Items), worker2Lease.ID[:8])
	fmt.Printf("Stats after worker 2 claim: %v\n", q.Stats())

	// Worker 3: Try to claim (will get fewer items)
	worker3Lease := q.ClaimBatch(30 * time.Second)
	if worker3Lease == nil {
		fmt.Println("Worker 3 claim returned nil (no pending items)")
	} else {
		fmt.Printf("Worker 3 claimed %d items\n", len(worker3Lease.Items))
	}
	fmt.Printf("Stats after worker 3 attempt: %v\n", q.Stats())

	// Simulate worker 1's lease expiring
	fmt.Println("\n--- Simulating Worker 1 lease expiration ---")
	expiredTime := worker1Lease.ExpiresAt.Add(1 * time.Second)
	released := q.ReleaseExpiredLeases(expiredTime)
	fmt.Printf("Released %d items from expired lease\n", released)
	fmt.Printf("Stats after expiration: %v\n", q.Stats())

	// Worker 2 can now ack its items
	itemsToAck = make([]string, 0)
	for _, item := range worker2Lease.Items {
		itemsToAck = append(itemsToAck, item.ID)
	}
	q.Ack(worker2Lease.ID, itemsToAck)
	fmt.Printf("Worker 2 acked %d items\n", len(itemsToAck))

	// Worker 4: Claim the items released from worker 1's expired lease
	worker4Lease := q.ClaimBatch(30 * time.Second)
	if worker4Lease != nil {
		fmt.Printf("Worker 4 claimed %d items (from expired lease)\n", len(worker4Lease.Items))
	}
	fmt.Printf("Final stats: %v\n", q.Stats())
}

